
import Automaton.DT_Automaton;
import Data.*;
import Models.*;
import Mu.DT_Mu;
import Services.*;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.Set;


/**
 * The {@code DT_DMS_Architecture} class connects all classes of the DT-DMS framework.
 * <p>
 * It is a Digital Twin ({@link DT_DMS}) with one named component of each kind: one data source, the three
 * types of models, the five types of services and the data assimilation function. Its collaboration
 * diagram (generated by Doxygen/Graphviz) is the architecture image of the framework.
 * </p>
 * <p>
 * Assign the fields, then call {@link #connect()} so that every component belongs to {@code D}, {@code M} or
 * {@code S} and is reached by {@code μ}.
 * </p>
 * <p>
 * Note: the fields are declared without their type argument (e.g., {@code DT_Data} instead of
 * {@code DT_Data<T>}) on purpose: Doxygen draws the relation to a class, with its parent classes, only for
 * this form. In your own code, use the typed form, as done in {@link #main}.
 * </p>
 *
 * @param <T> the type of a datum {@code d ∈ D}.
 */
@SuppressWarnings("rawtypes")
public class DT_DMS_Architecture<T> extends DT_DMS<T> {

    /** The data source ({@code D}). */
    DT_Data data = null;

    /** The descriptive model ({@code M_desc}). */
    DT_Model_Descriptive descriptiveModel = null;
    /** The predictive model ({@code M_pred}). */
    DT_Model_Predictive predictiveModel = null;
    /** The prescriptive model ({@code M_presc}). */
    DT_Model_Prescriptive prescriptiveModel = null;

    /** The monitoring service ({@code S_moni}). */
    DT_Service_Monitoring monitoring = null;
    /** The prediction service ({@code S_pred}). */
    DT_Service_Prediction prediction = null;
    /** The diagnosis service ({@code S_diag}). */
    DT_Service_Diagnosis diagnosis = null;
    /** The optimization service ({@code S_opti}). */
    DT_Service_Optimization optimization = null;
    /** The control service ({@code S_cont}). */
    DT_Service_Control control = null;

    /** The model inference or data assimilation function ({@code μ}); the same object as {@link #getMu()}. */
    DT_Mu assimilation = null;

    /**
     * Constructs the DT architecture.
     *
     * @param delta the freshness threshold {@code δ}.
     */
    public DT_DMS_Architecture(double delta) {
        super(delta);
        this.assimilation = mu;
    }

    /**
     * Adds every assigned field to the Digital Twin. Each service is coupled to a model of the matching
     * type: monitoring and diagnosis to the descriptive model, prediction to the predictive model,
     * optimization and control to the prescriptive model.
     */
    @SuppressWarnings("unchecked")
    public void connect() {
        if (data != null) addData(data);
        if (descriptiveModel != null) addModel(descriptiveModel);
        if (predictiveModel != null) addModel(predictiveModel);
        if (prescriptiveModel != null) addModel(prescriptiveModel);
        if (monitoring != null) addService(monitoring, descriptiveModel);
        if (prediction != null) addService(prediction, predictiveModel);
        if (diagnosis != null) addService(diagnosis, descriptiveModel);
        if (optimization != null) addService(optimization, prescriptiveModel);
        if (control != null) addService(control, prescriptiveModel);
    }

    /**
     * Example run of the framework on a temperature Digital Twin. Replace it with your own example.
     *
     * @param args not used.
     */
    public static void main(String[] args) {
        System.out.println("Welcome to DMS Framework.");

        // ---- DT = ⟨D, M, S, μ⟩ with a simulated clock: t_now = 100, δ = 5 → real-time window [95, 100]
        double[] now = {100.0};
        DT_DMS_Architecture<Double> dt = new DT_DMS_Architecture<>(5.0);
        dt.setName("Temperature");
        dt.setClock(() -> now[0]);

        // D, with the characterization of its data
        DT_Data<Double> data = new DT_Data<>("Sensor A", "Temperature");
        data.getCharacterization().setUnit("Celsius");
        data.getCharacterization().setSignalType("digital");
        data.getCharacterization().setDataFlowType("periodic");
        data.getCharacterization().setSensorPrecision("±0.1 °C");
        data.getCharacterization().setSensorCalibrationStatus("calibrated");
        // M = M_desc ∪ M_pred ∪ M_presc
        DT_Model_Descriptive<Double> descriptive = new DT_Model_Descriptive<>("Temperature summary", "Sensor A");
        DT_Model_Predictive<Double> predictive = new DT_Model_Predictive<>("Temperature forecast", "Moving average", 3);
        DT_Model_Prescriptive<Double> prescriptive = new DT_Model_Prescriptive<>("Temperature setpoint",
                "Keep temperature at 22", 22.0, "The heater reacts linearly");
        // S = S_moni ∪ S_pred ∪ S_diag ∪ S_opti ∪ S_cont
        DT_Service_Monitoring<Double> monitoring = new DT_Service_Monitoring<>("Temperature monitoring", null,
                "Sensor A", 10.0, 30.0);

        dt.data = data;
        dt.descriptiveModel = descriptive;
        dt.predictiveModel = predictive;
        dt.prescriptiveModel = prescriptive;
        dt.monitoring = monitoring;
        dt.prediction = new DT_Service_Prediction<Double>("Temperature prediction", null);
        dt.diagnosis = new DT_Service_Diagnosis<Double>("Temperature diagnosis", null, 10.0, 30.0);
        dt.optimization = new DT_Service_Optimization<Double>("Setpoint optimization", null, "Rule-based");
        dt.control = new DT_Service_Control<Double>("Heater control", null, "Proportional", 0.5);
        dt.connect();
        System.out.println(dt);

        // ---- μ: real-time data is assimilated synchronously, historical data asynchronously
        System.out.println("\n-- Data assimilation (μ)");
        data.updateData(99.0, 21.5);        // 99 ≥ 100 − 5 → real-time, assimilated at once
        data.updateData(80.0, 19.0);        // 80 < 100 − 5 → historical, queued
        System.out.println("Assimilated by the predictive model: " + predictive.getHistory()
                + ", waiting: " + dt.getMu().getPendingCount());
        dt.getMu().flush();                 // asynchronous assimilation of the queue
        System.out.println("After flush(): " + predictive.getHistory());

        // ---- a mixed segment ω = ω_hist ⊕ ω_rt is split at t_now − δ = 95
        DT_DataSegment<Double> omega = new DT_DataSegment<>();
        omega.put(90.0, 20.0);
        omega.put(96.0, 21.0);
        omega.put(98.0, 35.0);
        System.out.println("ω = " + omega + " is " + omega.kind(dt.tNow(), dt.getDelta())
                + ": ω_hist = " + omega.historicalPart(dt.tNow(), dt.getDelta())
                + ", ω_rt = " + omega.realTimePart(dt.tNow(), dt.getDelta()));
        dt.assimilate(omega);               // policy SPLIT: ω_rt at once, ω_hist queued
        dt.getMu().flush();

        // ---- D = D_hist ∪ D_rt
        System.out.println("\n-- Data (D)");
        System.out.println("D_rt   = " + dt.getRealTimeData());
        System.out.println("D_hist = " + dt.getHistoricalData());

        // ---- iterator pattern over the models
        System.out.println("\n-- Models (M)");
        for (dt.beginModels(); !dt.endModels(); dt.nextModel()) {
            dt.currentModel().executeModel();
        }

        // ---- services s : M × Ω_D → Y_s, run on the real-time segment ω_rt
        System.out.println("\n-- Services (S)");
        DT_DataSegment<Double> realTime = omega.realTimePart(dt.tNow(), dt.getDelta());
        for (dt.beginServices(); !dt.endServices(); dt.nextService()) {
            System.out.println(dt.currentService().getServiceName() + " → "
                    + dt.runService(dt.currentService(), realTime));
        }

        // ---- the monitoring service specified as an automaton 𝒮 = ⟨Λ, X, Y, Σ, Φ, Δ, Δ*⟩
        System.out.println("\n-- Automaton of the monitoring service");
        monitoring.addParameter("upperThreshold", 30.0);                                   // Λ
        monitoring.addInput("temperature");                                                // X
        monitoring.addOutput("alert");                                                     // Y
        monitoring.addStateVariable("value", 0.0);                                         // Σ
        monitoring.addPhase(new DT_Automaton.Phase("NORMAL", null, null, Double.POSITIVE_INFINITY));   // Φ
        monitoring.addPhase(new DT_Automaton.Phase("ALARM", null, null, 0.0));
        monitoring.addTransition(new DT_Automaton.Transition(DT_Automaton.TransitionKind.IN, "NORMAL", "ALARM",
                Set.of("temperature"), null, null,
                (q, x) -> { q.put("value", x.value); return q; }));                        // Δ^in
        monitoring.addTransition(new DT_Automaton.Transition(DT_Automaton.TransitionKind.TIME, "ALARM", "NORMAL",
                null, null,
                q -> List.of(new DT_Automaton.Event("alert", q.get("value"))),
                null));                                                                    // Δ^time
        monitoring.setInitialization(new DT_Automaton.Initialization("NORMAL", null, 0.0)); // Δ*
        monitoring.initialize();
        System.out.println("Phase: " + monitoring.getCurrentPhase());
        monitoring.externalTransition(new DT_Automaton.Event("temperature", 35.0), 1.0);
        System.out.println("Phase after input (temperature, 35.0): " + monitoring.getCurrentPhase()
                + ", state " + monitoring.getState());
        System.out.println("Output on internal transition: " + monitoring.internalTransition()
                + ", phase: " + monitoring.getCurrentPhase());

        // ---- validity of the DT: services versus models, models versus data, data versus services
        System.out.println("\n-- Validity");
        System.out.println("Consistent: " + dt.checkConsistency(System.out));

        // ---- the DT draws its own Data-Models-Services diagram (Graphviz)
        System.out.println("\n-- Graphviz");
        String dotFile = Files.isDirectory(Path.of("docs")) ? "docs/DT_DMS_Temperature.dot" : "DT_DMS_Temperature.dot";
        try {
            dt.dumpGraphviz(dotFile);
            System.out.println("Written " + dotFile + " (render it with: dot -Tpng " + dotFile + " -o DT_DMS_Temperature.png)");
        } catch (IOException e) {
            System.out.println("Cannot write " + dotFile + ": " + e.getMessage());
        }
    }
}
